from itertools import combinations
A=set(range(13))
B={13,14}
edges=[(u,v) for u in range(15) for v in range(u+1,15) if (u in A and v in B) or (u in B and v in A)]
print(len(edges))
print(edges)
# validate triangle-free and maximal
V=range(15); E=set(edges)
def has_edge(a,b):
    if a>b:a,b=b,a
    return (a,b) in E
tri=[]
for a,b,c in combinations(V,3):
    if has_edge(a,b) and has_edge(a,c) and has_edge(b,c): tri.append((a,b,c))
print('tri',tri[:5], len(tri))
bad=[]
for u,v in combinations(V,2):
    if not has_edge(u,v):
        if not any(has_edge(u,w) and has_edge(v,w) for w in V if w not in (u,v)):
            bad.append((u,v))
print('bad nonedges', bad[:10], len(bad))
